local QuenchBucketMaker = {}
local PRODUCTS = {
    iron_quenchbucket = { name = "Železni vedro za kaljenje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vedro za kaljenje za kovace." },
    bronze_quenchbucket = { name = "Bronast vedro za kaljenje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vedro za kaljenje za kovace." },
    silver_quenchbucket = { name = "Srebrn vedro za kaljenje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vedro za kaljenje za kovace." },
    gilded_quenchbucket = { name = "Pozlačen vedro za kaljenje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vedro za kaljenje za kovace." },
    jewel_set_quenchbucket = { name = "Draguljast vedro za kaljenje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vedro za kaljenje za kovace." },
    royal_sovereign_quenchbucket = { name = "Kraljevski suveren vedro za kaljenje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vedro za kaljenje z biseri za krono." },
}
local BUILDINGS = {
    quenchbucket_workshop = { name = "Quenchbucket delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    quenchbucket_house = { name = "Quenchbucket hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_quenchbucket_atelier = { name = "Mojstrski quenchbucket atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_quenchbucket_palace = { name = "Suverena quenchbucket palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
QuenchBucketMaker.ironStock = 14; QuenchBucketMaker.bronzeStock = 12; QuenchBucketMaker.woodStock = 12; QuenchBucketMaker.leatherStock = 12; QuenchBucketMaker.silverStock = 8; QuenchBucketMaker.goldStock = 6; QuenchBucketMaker.jewelStock = 4; QuenchBucketMaker.pearlStock = 4
QuenchBucketMaker.productStock = {}; QuenchBucketMaker.buildings = {}; QuenchBucketMaker.maker = nil; QuenchBucketMaker.activeMaking = {}; QuenchBucketMaker.totalProducts = 0; QuenchBucketMaker.dayTimer = 0
function QuenchBucketMaker.init() QuenchBucketMaker.ironStock=14; QuenchBucketMaker.bronzeStock=12; QuenchBucketMaker.woodStock=12; QuenchBucketMaker.leatherStock=12; QuenchBucketMaker.silverStock=8; QuenchBucketMaker.goldStock=6; QuenchBucketMaker.jewelStock=4; QuenchBucketMaker.pearlStock=4; QuenchBucketMaker.productStock={}; QuenchBucketMaker.buildings={}; QuenchBucketMaker.maker=nil; QuenchBucketMaker.activeMaking={}; QuenchBucketMaker.totalProducts=0; QuenchBucketMaker.dayTimer=0; print("[QuenchBucketMaker] Royal Quench Bucket Maker System initialized (6 products, 4 buildings)") end
function QuenchBucketMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuenchBucketMaker.maker={name=n or ("Kalilec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kalilec najet: %s (spretnost: %d)",QuenchBucketMaker.maker.name,s),"success") end; return true end
function QuenchBucketMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuenchBucketMaker.build(id) local ok,e=QuenchBucketMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuenchBucketMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuenchBucketMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuenchBucketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuenchBucketMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuenchBucketMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuenchBucketMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuenchBucketMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuenchBucketMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuenchBucketMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuenchBucketMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuenchBucketMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuenchBucketMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuenchBucketMaker.buildings==0 then return false,"Potrebna kalilna delavnica" end; if not QuenchBucketMaker.maker then return false,"Potreben kalilec" end; return true end
function QuenchBucketMaker.make(pt,qty) qty=qty or 1; local ok,e=QuenchBucketMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuenchBucketMaker.ironStock=QuenchBucketMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuenchBucketMaker.bronzeStock=QuenchBucketMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuenchBucketMaker.woodStock=QuenchBucketMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuenchBucketMaker.leatherStock=QuenchBucketMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuenchBucketMaker.silverStock=QuenchBucketMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuenchBucketMaker.goldStock=QuenchBucketMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuenchBucketMaker.jewelStock=QuenchBucketMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuenchBucketMaker.pearlStock=QuenchBucketMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuenchBucketMaker.maker then t=math.max(1,t-math.floor(QuenchBucketMaker.maker.skill/13)) end; table.insert(QuenchBucketMaker.activeMaking,{id="quenchbucket_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuenchBucketMaker.completeMaking(m) local q=1.0+(QuenchBucketMaker.getQualityBonus()/100); if QuenchBucketMaker.maker then q=q+(QuenchBucketMaker.maker.skill/140) end; q=math.min(2.5,q); QuenchBucketMaker.productStock[m.productType]=(QuenchBucketMaker.productStock[m.productType] or 0)+m.quantity; QuenchBucketMaker.totalProducts=QuenchBucketMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuenchBucketMaker.maker then QuenchBucketMaker.maker.itemsMade=QuenchBucketMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuenchBucketMaker.maker.skill=math.min(100,QuenchBucketMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vedro izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quenchbucket.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuenchBucketMaker.update(dt) if not _G.state then return end; QuenchBucketMaker.dayTimer=QuenchBucketMaker.dayTimer+dt; if QuenchBucketMaker.dayTimer>=30 then QuenchBucketMaker.dayTimer=0; for i=#QuenchBucketMaker.activeMaking,1,-1 do local m=QuenchBucketMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuenchBucketMaker.completeMaking(m); table.remove(QuenchBucketMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuenchBucketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuenchBucketMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuenchBucketMaker.getStats() return {ironStock=QuenchBucketMaker.ironStock,bronzeStock=QuenchBucketMaker.bronzeStock,woodStock=QuenchBucketMaker.woodStock,leatherStock=QuenchBucketMaker.leatherStock,silverStock=QuenchBucketMaker.silverStock,goldStock=QuenchBucketMaker.goldStock,jewelStock=QuenchBucketMaker.jewelStock,pearlStock=QuenchBucketMaker.pearlStock,productStock=QuenchBucketMaker.productStock,numBuildings=#QuenchBucketMaker.buildings,hasMaker=QuenchBucketMaker.maker~=nil,makerName=QuenchBucketMaker.maker and QuenchBucketMaker.maker.name or "—",makerSkill=QuenchBucketMaker.maker and QuenchBucketMaker.maker.skill or 0,activeMaking=#QuenchBucketMaker.activeMaking,totalProducts=QuenchBucketMaker.totalProducts} end
return QuenchBucketMaker
